(184, 63, 'السلام عليكم ورحمة الله وبركاته', NULL, NULL, 1, 2, 0, 0, 1, 0, 1, '2025-08-17 16:00:37', '2025-08-17 22:10:10', NULL),
(185, 63, 'الرجاء الدعاء لأهلنا في غزة خاصة في صلاة الفجر فهم في امس الحاجة', NULL, NULL, 1, 2, 0, 0, 1, 0, 1, '2025-08-17 16:01:29', '2025-08-17 22:10:07', NULL),
